package com.google.javascript.jscomp;

import com.google.common.base.Preconditions;
import com.google.common.collect.Lists;
import com.google.common.collect.Maps;
import com.google.common.collect.Sets;
import com.google.javascript.jscomp.AbstractCompiler.LifeCycleStage;
import com.google.javascript.jscomp.MakeDeclaredNamesUnique.BoilerplateRenamer;
import com.google.javascript.jscomp.NodeTraversal.AbstractPostOrderCallback;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.Scope.Var;
import com.google.javascript.jscomp.testing.CompilerTestCase;
import com.google.javascript.jscomp.testing.TestEval;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Normalize_process_TriageGen0Test extends CompilerTestCase {

  /**
   * Tests the standard execution path where MAKE_LOCAL_NAMES_UNIQUE is true.
   * Covers line coverage for the traversal, renaming, duplicate removal, 
   * constant propagation, and lifecycle stage update.
   */
  @Test
  public void testProcess_StandardPath() {
    // Using a simple script to ensure all steps execute
    String code = "function f(e) { try { throw 0; } catch(e) { var e2 = 1; } var e = 2; }";
    Compiler compiler = new Compiler();
    SourceFile input = parseCode(code);

    // We need to mock or ensure the environment allows Normalize to run.
    // Since we are testing the 'process' method of Normalize, we trigger it via the compiler.
    // In Closure Compiler, Normalize is typically part of the pipeline.

    CompilationLevel.INPUT_OPTIMIZATIONS.setOptionsForCompilationLevel(compiler);
    compiler.compile(externs, input, null);

    // Verify the compiler reached NORMALIZED stage
    assertNotNull(compiler.getLifeCycleStage());
    // The process method explicitly sets this if not already set
    // Note: In a real integration, this is set by the pass manager.
  }

  /**
   * Tests the branch where MAKE_LOCAL_NAMES_UNIQUE is false.
   * This requires manipulating the static field if possible, or relying on 
   * the fact that we are testing the logic flow. 
   * Since MAKE_LOCAL_NAMES_UNIQUE is likely a static boolean in Normalize, 
   * we assume the test environment allows testing both branches.
   */
  @Test
  public void testProcess_WithoutMakeLocalNamesUnique() {
    // This test simulates the code path where the 'if (MAKE_LOCAL_NAMES_UNIQUE)' block is skipped.
    // Because we cannot easily change a static final field in a standard JUnit test 
    // without reflection, we rely on the provided code structure.

    String code = "var x = 1; var x = 2;"; 
    Compiler compiler = new Compiler();
    SourceFile input = parseCode(code);

    // We manually invoke the process to test the logic
    Normalize normalize = new Normalize(compiler, false);
    Node externs = new Node(NodeType.VAR, null);
    Node root = parseCode(code).toNode();

    normalize.process(externs, root);

    // Verify lifecycle stage was updated
    assertEquals(LifeCycleStage.NORMALIZED, compiler.getLifeCycleStage());
  }

  /**
   * Tests the specific logic mentioned in the comments regarding catch block scope.
   * "function f() { try {throw 0;} catch(e) {e; /* catch scope 'e'*/} var e = 1; }"
   * This ensures that removeDuplicateDeclarations and MakeDeclaredNamesUnique 
   * work together to prevent 'var e = 1' from being rewritten to 'e = 1'.
   */
  @Test
  public void testProcess_CatchBlockScopeHandling() {
    String code = "function f() { try { throw 0; } catch(e) { var x = 1; } var e = 2; }";
    Compiler compiler = new Compiler();
    SourceFile input = parseCode(code);

    // Set up compiler options to include normalization
    compiler.compile(externs, input, null);

    // If the logic is correct, the 'var e = 2' should remain a declaration 
    // and not be converted to an assignment 'e = 2' due to the catch 'e'.
    String result = compiler.toSource();
    assertTrue("Should preserve variable declaration", result.contains("var e = 2"));
  }

  /**
   * Tests the branch where the compiler is already in the NORMALIZED stage.
   * This covers the 'if (!compiler.getLifeCycleStage().isNormalized())' branch.
   */
  @Test
  public void testProcess_AlreadyNormalized() {
    Compiler compiler = new Compiler();
    compiler.setLifeCycleStage(LifeCycleStage.NORMALIZED);

    Normalize normalize = new Normalize(compiler, false);
    Node externs = new Node(NodeType.VAR, null);
    Node root = new Node(NodeType.SCRIPT, null);

    // Should not throw exception and should handle the stage check gracefully
    normalize.process(externs, root);

    assertEquals(LifeCycleStage.NORMALIZED, compiler.getLifeCycleStage());
  }
}
